contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (amount)); require(amount <= 1000000000000000000000000000000);
        require(address(this).balance >= amount);

        uint beforeUserBal = c.getBalance(address(this)); if (__ESBMC_reverted()) return;
        uint beforeCBal = address(c).balance;

        c.addToBalance{value: amount}(); if (__ESBMC_reverted()) return;

        uint afterUserBal = c.getBalance(address(this)); if (__ESBMC_reverted()) return;
        uint afterCBal = address(c).balance;

        assert(afterUserBal >= beforeUserBal && afterCBal >= beforeCBal);
    }

    receive() external payable {}
}

